typedef float rational_t;
typedef unsigned int uint32;

class vector3d
{
public:
  vector3d(rational_t, rational_t, rational_t);
};

class color32
{
public:
  uint32 value;
};

class po
{
public:
  po(const vector3d &, const vector3d &, const vector3d &, const vector3d &);
};

class region;
class camera
{
public:
  region *get_region();
};

class game
{
public:
  camera *get_current_view_camera();
};

class app
{
public:
  static app *inst();
  game *get_game();
};

class instance_render_info
{
public:
  instance_render_info(int, const po &, int, region *, int, color32, int);
};

class vr_pmesh
{
public:
  int get_max_faces() const;
  void render_instance(int, instance_render_info *);
};

extern vr_pmesh *global_cap_base;
extern vr_pmesh *global_cap_end;

enum
{
  FORCE_TRANSLUCENCY = 1,
  RENDER_TRANSLUCENT_PORTION = 1,
  RENDER_CLIPPED_FULL_DETAIL = 2,
  RENDER_REAL_POINT_LIGHTS = 4
};

void render_sphere(const vector3d &pos, rational_t radius, color32 col)
{
#ifndef BUILD_BOOTABLE
  if (radius < 0.05f) radius = 0.05f;

  vector3d right(radius, 0, 0), up(0, radius, 0), forward(0, 0, radius);
  po m(right,up,forward,pos);

  instance_render_info iri(global_cap_base->get_max_faces(), m, 0, app::inst()->get_game()->get_current_view_camera()->get_region(), 0, col, FORCE_TRANSLUCENCY );
  global_cap_base->render_instance(RENDER_TRANSLUCENT_PORTION|RENDER_CLIPPED_FULL_DETAIL|RENDER_REAL_POINT_LIGHTS, &iri);
  global_cap_end->render_instance(RENDER_TRANSLUCENT_PORTION|RENDER_CLIPPED_FULL_DETAIL|RENDER_REAL_POINT_LIGHTS, &iri);
#endif
}
